from audit_common import *
import torch,fcntl
from torch.nn import functional as F
def main():
 frozen();lock=(P/'runs/gpu.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);torch.set_num_threads(4);helpers=module('precision_original_common',OLD/'source/common.py');Net=module('precision_original_transition',OLD/'source/transition.py').LatentTransition;meta=read(TRAIN/'data/_private/evaluation_metadata.json');ids=np.array([i for i,r in enumerate(meta)if r['split']=='dev']);z=dict(np.load(TRAIN/'data/public/inputs.npz'));t=dict(np.load(TRAIN/'data/_private/targets.npz'));out=[]
 for precision,dtype in [('high',torch.float32),('highest',torch.float64)]:
  torch.set_float32_matmul_precision(precision);m=helpers.reader().to(dtype=dtype);net=Net('full').cuda().to(dtype=dtype);net.load_state_dict(torch.load(TRAIN/'models/aug132_seed0/update0300.pt',map_location='cuda',weights_only=False)['model']);params=tuple(net.parameters());d={k:torch.as_tensor(z[k][ids],device='cuda',dtype=dtype)for k in ['current_objects','current_scene','declared_actions']};h,s=net(**d);lp=helpers.logits(m,h,s);y=torch.as_tensor(t['after_y'][ids],device='cuda',dtype=dtype);v=torch.as_tensor(t['after_valid'][ids],device='cuda');weights=torch.tensor(read(TRAIN/'configs/protocol.json')['class_weights_common_to_both_cohorts'],device='cuda',dtype=dtype);raw=F.binary_cross_entropy_with_logits(lp,y,reduction='none');parts=[]
  for gi,cols in enumerate([[0,1,2],[3,4,5],[6]]):w=torch.where(y[:,cols]>.5,weights[gi,1],weights[gi,0]);parts.append((raw[:,cols]*w*v[:,cols]).sum()/v[:,cols].sum()/3)
  parts.extend([.025*F.smooth_l1_loss(h,torch.as_tensor(t['next_objects'][ids],device='cuda',dtype=dtype)),.025*F.smooth_l1_loss(s,torch.as_tensor(t['next_scene'][ids],device='cuda',dtype=dtype))]);flatten=lambda gs:torch.cat([(torch.zeros_like(p)if g is None else g).reshape(-1)for g,p in zip(gs,params)]);separate=sum(flatten(torch.autograd.grad(c,params,retain_graph=True,allow_unused=True))for c in parts);joint=flatten(torch.autograd.grad(sum(parts),params,allow_unused=True));delta=separate-joint;out.append({'precision':precision,'dtype':str(dtype),'checkpoint':'aug132_seed0_update0300','dataset':'C42','component_sum_vs_joint_max_abs':float(delta.abs().max()),'component_sum_vs_joint_relative_L2':float(delta.norm()/joint.norm()),'joint_gradient_L2':float(joint.norm()),'separate_gradient_L2':float(separate.norm()),'parameters_unchanged_no_optimizer':True})
 save(E/'results/gradient_precision_check.json',{'created_utc':now(),'reason':'Initial per-coordinate 2e-6 absolute gradient-sum assertion failed under original high matmul precision; inspect relative norm and double precision before adjusting diagnostic tolerance.','checks':out,'D_forward_calls':0,'optimizer_updates':0});print(json.dumps(out),flush=True)
